using System.Globalization;
using System.Text.Json;

namespace Vybe.GameRules.Tests;

/// <summary>Cross-language parity: C# must reproduce every fixture generated by the TS reference.</summary>
public sealed class GoldenFixtureTests
{
    public static TheoryData<string> ScoringFixtures() => new(FixtureFiles.List("scoring"));

    public static TheoryData<string> RejectionFixtures() => new(FixtureFiles.List("rejections"));

    [Fact]
    public void Pcg32_MatchesEveryVector()
    {
        var file = FixtureFiles.Read<PcgFile>("pcg32.json");
        Assert.NotEmpty(file.Vectors);

        foreach (var vector in file.Vectors)
        {
            var rng = new Pcg32(
                ulong.Parse(vector.InitState, CultureInfo.InvariantCulture),
                ulong.Parse(vector.InitSeq, CultureInfo.InvariantCulture));
            var actual = vector.Outputs.Select(_ => rng.NextUInt32()).ToArray();
            Assert.Equal(vector.Outputs, actual);
        }
    }

    [Fact]
    public void RulesetChecksum_MatchesCanonicalJsonOfConfig()
    {
        using var document = FixtureFiles.ReadDocument("rulesets/street-hoops-v1.json");
        var root = document.RootElement;
        var expected = root.GetProperty("checksum").GetString();

        Assert.Matches("^[0-9a-f]{64}$", expected);
        Assert.Equal(expected, CanonicalJson.Checksum(root.GetProperty("config")));
    }

    [Theory]
    [MemberData(nameof(ScoringFixtures))]
    [MemberData(nameof(RejectionFixtures))]
    public void Evaluate_ReproducesFixture(string relativePath)
    {
        var fixture = FixtureFiles.Read<Fixture>(relativePath);

        var waypoints = StreetHoopsSimulator.GenerateWaypoints(fixture.Input.Config, fixture.Input.Seed);
        Assert.Equal(fixture.Waypoints, waypoints);

        var result = StreetHoopsSimulator.Evaluate(fixture.Input);
        var actual = JsonSerializer.SerializeToElement(result, FixtureFiles.JsonOptions);
        Assert.Equal(CanonicalJson.Serialize(fixture.Expected), CanonicalJson.Serialize(actual));
    }

    [Fact]
    public void FixtureDirectories_AreNotEmpty()
    {
        Assert.NotEmpty(FixtureFiles.List("scoring"));
        Assert.NotEmpty(FixtureFiles.List("rejections"));
    }
}
